function foodPage({ slug, titleKw, desc, h1, items, note, intro, tips, faqs }) {
  addPage(slug, AR({
    url: `${SITE}/${slug}/`,
    title: `${titleKw} في العبور: القائمة الموثقة بالأرقام | دليل العبور`,
    description: desc,
    h1,
    tag: "⌖ مطاعم وأكل",
    crumbs: crumb("المطاعم", "/restaurants/", titleKw, `/${slug}/`),
    body: `
<p>${intro}</p>
${items.length ? dataTable(items, `${srcNote} ${note} (${items.length} كيان):`) : `<p>التوثيق جارٍ لهذه الفئة — القائمة الكاملة للمطاعم في <a href="/restaurants/">دليل مطاعم العبور</a>.</p>`}
<h2>نصائح الطلب والزيارة</h2>
${tips}
${verifyNote}`,
    extraSchemas: [itemListSchema(`${titleKw} في العبور`, `${SITE}/${slug}/`, items.length)],
    faq: faqs,
  }));
}

